const fn assert_tags_are_equal(failure_description: &str, a: &[u32], b: &[u32]) {
    if a.len() != b.len() {
        {
            ::core::panicking::panic_display(&failure_description);
        };
    }
    let mut i = 0;
    while i < a.len() {
        if a[i] != b[i] {
            {
                ::core::panicking::panic_display(&failure_description);
            };
        }
        i += 1;
    }
}
